async function retryWithBackoff(fn, {
  maxAttempts = 5,
  baseDelayMs = 500,
  maxDelayMs = 8000,
  isRetryable = (err) => err.code === 'ETIMEDOUT' || err.code === 'ECONNRESET'
} = {}) {
  let attempt = 0;

  while (true) {
    try {
      return await fn();
    } catch (err) {
      attempt += 1;

      if (!isRetryable(err) || attempt >= maxAttempts) {
        throw err;
      }

      const rawDelay = Math.min(baseDelayMs * 2 ** (attempt - 1), maxDelayMs);
      const jitter = rawDelay * (0.5 + Math.random() * 0.5);
      await new Promise((resolve) => setTimeout(resolve, jitter));
    }
  }
}

